#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

namespace Campground.Shared.Registry
{
    /// <summary>What a plugin owns. One registration per plugin; registering again replaces it.</summary>
    /// <param name="PluginId">The owner, as in <see cref="PluginIds"/>.</param>
    /// <param name="PathRoots">Folders whose contents are the plugin's items (GameTent's shelves folder).</param>
    /// <param name="ProviderIdKeys">Provider id names the plugin puts on its items (an item carrying a non-empty one is the plugin's).</param>
    /// <param name="FolderIds">Library (CollectionFolder) ids the plugin owns.</param>
    /// <param name="AccessManagedByOwner">
    /// True when the plugin sets who may open its libraries (FieldGuide). Bonfire then leaves those libraries alone:
    /// it neither grants nor blocks them. False when the admin chooses (GameTent's Shelf), so Bonfire manages
    /// access as it does for any library. Whoever sets this true owns the access rules for those libraries.
    /// </param>
    internal sealed record OwnershipRegistration(
        string PluginId,
        IReadOnlyList<string> PathRoots,
        IReadOnlyList<string> ProviderIdKeys,
        IReadOnlyList<string> FolderIds,
        bool AccessManagedByOwner);

    /// <summary>The answer to "who owns this library".</summary>
    /// <param name="ByReservedPrefix">True when the answer came only from the library's name or its folder's name (see <see cref="Ownership.ReservedLibraryPrefixes"/> and <see cref="Ownership.FieldGuideFolderMarker"/>), not from a registration.</param>
    internal sealed record LibraryOwner(string PluginId, bool AccessManagedByOwner, bool ByReservedPrefix);

    /// <summary>
    /// Item and library ownership (issue #31, item 1). Standalone, with nothing registered, every answer is "not
    /// owned" (a library whose name carries a reserved prefix still counts: that is known without any plugin).
    /// <para>
    /// <see cref="OwnerOf"/> is for <b>items</b> and answers only from registered path roots and provider ids, never
    /// from the libraries an item sits in. The same film in FieldGuide's library and its original library is one
    /// item (its id is made from the path), so a library-based answer would take it away from its original library.
    /// <see cref="LibraryOwnerOf"/> is for <b>library-level</b> decisions only (Bonfire's policy sync and library
    /// screens). Never use it to decide who owns an item.
    /// </para>
    /// <para>
    /// Jellyfin's live objects can't be built in a test, so both lookups take plain values; the plugin's adapter
    /// reads them off the item or library.
    /// </para>
    /// </summary>
    internal static class Ownership
    {
        internal const string SectionName = "ownership";

        /// <summary>FieldGuide's per-user libraries are named "For You: &lt;name&gt;".</summary>
        internal const string ForYouPrefix = "For You:";

        /// <summary>
        /// Library-name prefixes reserved to a plugin, known before any plugin loads, so a library that has one is
        /// owned (with <c>AccessManagedByOwner</c> true) even before its plugin has registered or after it is
        /// uninstalled. Matched ordinally, so "for you:" is an ordinary name. An admin who names a library this way
        /// takes it out of Bonfire's management; nothing is granted or blocked, so nothing opens up.
        /// </summary>
        /// <remarks>
        /// FieldGuide translates its row names (FieldGuide F68), and a prefix missing from Bonfire 2.0's frozen copy
        /// would be unprotected after a restart, so every language FieldGuide ships is here from 0.8.0. FieldGuide
        /// ships exactly these strings: plain ASCII colon, no space before it.
        /// </remarks>
        internal static readonly IReadOnlyList<KeyValuePair<string, string>> ReservedLibraryPrefixes = new[]
        {
            new KeyValuePair<string, string>(ForYouPrefix, PluginIds.FieldGuide),  // en
            new KeyValuePair<string, string>("Para ti:", PluginIds.FieldGuide),    // es
            new KeyValuePair<string, string>("Pour vous:", PluginIds.FieldGuide),  // fr
            new KeyValuePair<string, string>("Für dich:", PluginIds.FieldGuide),   // de
            new KeyValuePair<string, string>("Per te:", PluginIds.FieldGuide),     // it
            new KeyValuePair<string, string>("Para você:", PluginIds.FieldGuide),  // pt-BR
            new KeyValuePair<string, string>("Para si:", PluginIds.FieldGuide),    // pt-PT
            new KeyValuePair<string, string>("Voor jou:", PluginIds.FieldGuide),   // nl
            new KeyValuePair<string, string>("Dla Ciebie:", PluginIds.FieldGuide), // pl
            new KeyValuePair<string, string>("Senin için:", PluginIds.FieldGuide), // tr
            new KeyValuePair<string, string>("Для вас:", PluginIds.FieldGuide),    // ru, uk
            new KeyValuePair<string, string>("Per a tu:", PluginIds.FieldGuide),   // ca
            new KeyValuePair<string, string>("För dig:", PluginIds.FieldGuide),    // sv
            new KeyValuePair<string, string>("Til dig:", PluginIds.FieldGuide),    // da
            new KeyValuePair<string, string>("For deg:", PluginIds.FieldGuide),    // nb
            new KeyValuePair<string, string>("Sinulle:", PluginIds.FieldGuide),    // fi
            new KeyValuePair<string, string>("Pro vás:", PluginIds.FieldGuide),    // cs
            new KeyValuePair<string, string>("Neked:", PluginIds.FieldGuide),      // hu
            new KeyValuePair<string, string>("Για εσάς:", PluginIds.FieldGuide),   // el
            new KeyValuePair<string, string>("おすすめ:", PluginIds.FieldGuide),    // ja
            new KeyValuePair<string, string>("为你推荐:", PluginIds.FieldGuide),    // zh-Hans
            new KeyValuePair<string, string>("為你推薦:", PluginIds.FieldGuide),    // zh-Hant
            new KeyValuePair<string, string>("추천:", PluginIds.FieldGuide),        // ko
        };

        /// <summary>
        /// FieldGuide creates every library folder as <c>fieldguide-&lt;id&gt;</c> and sets the display name over it
        /// (FieldGuide F41). A library whose own folder's last segment starts with this (ordinal, case ignored) is
        /// FieldGuide's, managed, whatever language its name is in. The prefixes above stay, because F41 is still
        /// to be proven.
        /// </summary>
        internal const string FieldGuideFolderMarker = "fieldguide-";

        // Registry layout (section "ownership"): plugin id -> the registration as a JsonElement (a BCL type, so
        // another loaded copy of this library can read it). The section is a ConcurrentDictionary, so each write
        // and read is atomic on its own with no lock. Entries are stamped with the host generation by
        // CampgroundLifetime and dropped when it is old, and withdrawn on ApplicationStopping, like capabilities.
        // A reader works on the values it enumerated, so a registration replaced mid-read is simply seen old or
        // new, never half-written.

        /// <summary>Registers or replaces this plugin's registration.</summary>
        internal static void Register(OwnershipRegistration registration)
        {
            // Boxed once, so the generation stamp and the stored value are the same object.
            object stored = CampgroundRegistry.ToJson(registration);
            CampgroundLifetime.Stamp(stored);
            CampgroundRegistry.Section(SectionName)[registration.PluginId] = stored;
        }

        /// <summary>Removes this plugin's registration (on <c>ApplicationStopping</c>, or when it is switched off).</summary>
        internal static void Withdraw(string pluginId)
            => CampgroundRegistry.Section(SectionName).TryRemove(pluginId, out _);

        /// <summary>
        /// The plugin that owns an item, or null. Answers only from path roots and provider ids, never from the
        /// libraries the item is in.
        /// </summary>
        /// <param name="itemPath">The item's file path (may be null for virtual items).</param>
        /// <param name="providerIds">The item's provider ids (name to value).</param>
        internal static string? OwnerOf(string? itemPath, IReadOnlyDictionary<string, string>? providerIds)
        {
            foreach (var r in Registrations())
            {
                if (itemPath != null && r.PathRoots.Any(root => IsUnder(itemPath, root)))
                {
                    return r.PluginId;
                }

                if (providerIds != null
                    && r.ProviderIdKeys.Any(key => providerIds.TryGetValue(key, out var v) && !string.IsNullOrWhiteSpace(v)))
                {
                    return r.PluginId;
                }
            }

            return null;
        }

        /// <summary>
        /// The plugin that owns a library, or null. Owned when its name has a reserved prefix, when its id is a
        /// registered folder id, or when it has locations and all of them sit under a registered root. For
        /// library-level decisions only.
        /// </summary>
        /// <param name="folderId">The library's CollectionFolder id (dashes and case don't matter).</param>
        /// <param name="libraryName">The library's name.</param>
        /// <param name="locations">The library's folder paths.</param>
        /// <param name="folderPath">The library's own folder (its CollectionFolder path), for <see cref="FieldGuideFolderMarker"/>.</param>
        internal static LibraryOwner? LibraryOwnerOf(
            string? folderId, string? libraryName, IReadOnlyCollection<string>? locations, string? folderPath = null)
        {
            // The reserved prefix and folder marker first: they are reserved, so a registration can't turn them into
            // a managed library.
            if (!string.IsNullOrEmpty(libraryName))
            {
                foreach (var pair in ReservedLibraryPrefixes)
                {
                    if (libraryName.StartsWith(pair.Key, StringComparison.Ordinal))
                    {
                        return new LibraryOwner(pair.Value, true, true);
                    }
                }
            }

            if (!string.IsNullOrEmpty(folderPath))
            {
                var segment = folderPath.TrimEnd('/', '\\');
                var cut = Math.Max(segment.LastIndexOf('/'), segment.LastIndexOf('\\'));
                segment = cut >= 0 ? segment.Substring(cut + 1) : segment;
                if (segment.Length > FieldGuideFolderMarker.Length
                    && segment.StartsWith(FieldGuideFolderMarker, StringComparison.OrdinalIgnoreCase))
                {
                    return new LibraryOwner(PluginIds.FieldGuide, true, true);
                }
            }

            var id = NormalizeId(folderId);
            foreach (var r in Registrations())
            {
                if (id.Length > 0 && r.FolderIds.Any(f => NormalizeId(f) == id))
                {
                    return new LibraryOwner(r.PluginId, r.AccessManagedByOwner, false);
                }

                if (locations != null && locations.Count > 0
                    && locations.All(loc => r.PathRoots.Any(root => IsUnder(loc, root))))
                {
                    return new LibraryOwner(r.PluginId, r.AccessManagedByOwner, false);
                }
            }

            return null;
        }

        private static IEnumerable<OwnershipRegistration> Registrations()
        {
            var section = CampgroundRegistry.Section(SectionName);
            foreach (var pair in section)
            {
                if (CampgroundLifetime.IsStale(pair.Value))
                {
                    section.TryRemove(pair);   // only this exact value, so a newer registration stays
                    continue;
                }

                if (pair.Value is JsonElement e)
                {
                    OwnershipRegistration? r = null;
                    try
                    {
                        r = CampgroundRegistry.FromJson<OwnershipRegistration>(e);
                    }
                    catch (JsonException)
                    {
                        // A malformed entry owns nothing.
                    }

                    if (r != null)
                    {
                        yield return Clean(r);
                    }
                }
            }
        }

        // Missing lists (a registration written by a different version) read as empty.
        private static OwnershipRegistration Clean(OwnershipRegistration r)
            => r with
            {
                PathRoots = r.PathRoots ?? Array.Empty<string>(),
                ProviderIdKeys = r.ProviderIdKeys ?? Array.Empty<string>(),
                FolderIds = r.FolderIds ?? Array.Empty<string>(),
            };

        private static string NormalizeId(string? id)
            => string.IsNullOrWhiteSpace(id) ? string.Empty : id.Replace("-", string.Empty).Trim().ToLowerInvariant();

        // True when path is the root or sits inside it, at a folder boundary ("shelves-old" is not under "shelves").
        // Either slash style. Case matters on Linux and not on Windows, like the file system. Paths aren't resolved:
        // a ".." in either is the caller's to have cleaned, and an empty root never matches.
        private static bool IsUnder(string path, string root)
        {
            var r = Trim(root);
            if (r.Length == 0)
            {
                return false;
            }

            var p = Trim(path);
            var cmp = OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
            return p.Equals(r, cmp) || (p.Length > r.Length && p.StartsWith(r + "/", cmp));
        }

        private static string Trim(string s) => s.Trim().Replace('\\', '/').TrimEnd('/');
    }
}
